/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var log = require( './../log.js' );
var config = require( './../config.js' );


// VARIABLES //

var URL_PREFIX = config.routes.config;


// FUNCTIONS //

/**
* Returns request options.
*
* @private
* @param {string} body - request body
* @returns {Object} options object
*/
function requestOptions( body ) {
	return {
		'method': 'POST',
		'headers': {
			'Content-Type': 'text/plain'
		},
		'body': body,
		'credentials': 'same-origin'
	};
}


// MAIN //

/**
* Callback invoked upon changing a value in the editor.
*
* @private
* @param {Event} event - event object
*/
function onChange( event ) {
	var self;
	var conf;
	var prop;
	var url;
	var ns;

	self = this;
	conf = this._config;

	// FIXME: other properties/objects

	switch ( event.object ) {
	case conf.general:
		ns = '';
		break;
	case conf.padding:
		ns = 'padding';
		break;
	case conf.title:
		ns = 'title';
		break;
	default:
		break;
	}
	// Resolve the property name by removing any units:
	prop = event.property.split( ' ' )[ 0 ];

	log( 'Editor changed: %s/%s', ns, prop );
	this.emit( 'change', {
		'type': 'change',
		'source': 'editor',
		'property': event.property,
		'path': [ ns, prop ],
		'value': event.value
	});

	log( 'Attempting to update configuration...' );
	url = URL_PREFIX+'/'+( ( ns ) ? ns+'/' : ns )+prop;
	fetch( url, requestOptions( event.value.toString() ) )
		.then( onResponse )
		.catch( onError );

	/**
	* Callback invoked upon receiving an HTTP response.
	*
	* @private
	* @param {Response} response - response object
	* @returns {void}
	*/
	function onResponse( response ) {
		if ( response.ok ) {
			log( 'Successfully updated configuration.' );
			return;
		}
		console.error( 'Encountered an error when posting change. Status: %d.', response.status );

		// If we failed, we need to roll back to displaying the value from the existing visualization schema:
		self.refresh();
	}

	/**
	* Callback invoked upon encountering an error.
	*
	* @private
	* @param {Error} error - error object
	*/
	function onError( error ) {
		console.error( 'Encountered an error when posting change. Error: %s.', error.message );

		// If we failed, we need to roll back to displaying the value from the existing visualization schema:
		self.refresh();
	}
}


// EXPORTS //

module.exports = onChange;
